        json="{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"\$defs\":{\"ACBusType\":{\"description\":\"Classification of an AC bus for power flow, following the MATPOWER bus-type convention. `PQ` fixes the active and reactive injections and solves for voltage magnitude and angle; `PV` fixes active power and voltage magnitude and solves for reactive power and angle; `REF` names the reference for the system voltage angle; `SLACK` balances the system active and reactive mismatch and sets the reference angle; `ISOLATED` marks a bus not connected to the network.\",\"enum\":[\"PQ\",\"PV\",\"REF\",\"ISOLATED\",\"SLACK\"],\"title\":\"ACBusType\",\"type\":\"string\"},\"AverageRateCurve\":{\"description\":\"A curve whose y values are the average rate `f(x)/x` at production level `x` — total cost or fuel divided by output, the form heat rate tables use when they report MBTU/MWh against MW. `initial_input` records the total input at the minimum production point and is what makes conversion to an `InputOutputCurve` possible. Use `IncrementalCurve` when the data gives marginal rather than average rates.\",\"properties\":{\"curve_type\":{\"const\":\"AVERAGE_RATE\",\"type\":\"string\",\"default\":\"AVERAGE_RATE\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/LinearFunctionData\",\"PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\"},\"input_at_zero\":{\"type\":\"number\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"AverageRateCurve\",\"type\":\"object\"},\"ComplexNumber\":{\"description\":\"A complex number, given as its `real` and `imag` parts.\",\"properties\":{\"real\":{\"type\":\"number\"},\"imag\":{\"type\":\"number\"}},\"title\":\"ComplexNumber\",\"type\":\"object\"},\"CostCurve\":{\"description\":\"Variable operation cost of a device expressed directly in currency. Wraps a `ValueCurve` that may be in input-output, incremental, or average-rate form, with `power_units` declaring the basis of the x axis and `vom_cost` adding a proportional variable operation and maintenance term.\",\"properties\":{\"power_units\":{\"default\":\"NATURAL_UNITS\",\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/UnitSystem\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/ValueCurve\"},\"variable_cost_type\":{\"const\":\"COST\",\"type\":\"string\",\"default\":\"COST\"},\"vom_cost\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/InputOutputCurve\"}},\"required\":[\"value_curve\",\"power_units\",\"vom_cost\",\"variable_cost_type\"],\"title\":\"CostCurve\",\"type\":\"object\"},\"DbdPnts\":{\"description\":\"A pair of deadband thresholds `(dbd1, dbd2)` on a voltage or reactive-power error signal, inside which the controller does not act.\",\"properties\":{\"dbd1\":{\"type\":\"number\"},\"dbd2\":{\"type\":\"number\"}},\"title\":\"DbdPnts\",\"type\":\"object\"},\"EmissionBasis\":{\"description\":\"What an emission rate is measured against: `FUEL_INPUT` for mass per unit of heat input, `POWER_OUTPUT` for mass per unit of electrical output. The choice constrains the accompanying energy unit — a heat unit for `FUEL_INPUT`, `MWH` for `POWER_OUTPUT`.\",\"enum\":[\"FUEL_INPUT\",\"POWER_OUTPUT\"],\"title\":\"EmissionBasis\",\"type\":\"string\"},\"EnergyUnit\":{\"description\":\"Energy unit forming the denominator of an