napi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/RenewableGenerationCost\",\"THERMAL\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/ThermalGenerationCost\",\"HYDRO_GEN\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/HydroGenerationCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/ThermalGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/RenewableGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/HydroGenerationCost\"}],\"title\":\"GenericOperationCost\",\"type\":\"object\"},\"HydroGenerationCost\":{\"description\":\"Cost representation for hydro gen units\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_GEN\",\"type\":\"string\",\"default\":\"HYDRO_GEN\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-0936a17371037c3b813d.json#/\$defs/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"HydroGenerationCost\",\"type\":\"object\"},\"HydroReservoirCost\":{\"description\":\"Cost representation for hydro reservoir\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_RES\",\"type\":\"string\",\"default\":\"HYDRO_RES\"},\"level_shortage_cost\":{\"default\":0.0,\"type\":\"number\"},\"level_surplus_cost\":{\"default\":0.0,\"type\":\"number\"},\"spillage_cost\":{\"default\":0.0,\"type\":\"number\"}},\"title\":\"HydroReservoirCost\",\"type\":\"object\"},\"HydroStorageGenerationCost\":{\"description\":\"Operating cost of hydro generation with storage, selected by `cost_type` between the hydro generation (`HYDRO_GEN`) and storage (`STORAGE`) cost representations.\",\"title\":\"HydroStorageGenerationCost\",\"type\":\"object\",\"discriminator\":{\"mapping\":{\"HYDRO_GEN\":\"https://openapi.invalid/sch